import Foundation
import XCTest

/// Loads fixtures committed under `Tests/VaultKitTests/Fixtures`.
///
/// The fixtures are generated by an *independent* implementation
/// (`tools/derive/`, Python + pycryptodome) or copied verbatim from the
/// published standards (BIP39 wordlist and Trezor vectors), so tests that use
/// them are differential rather than self-referential.
enum FixtureLoader {
    static func url(_ name: String, extension ext: String) throws -> URL {
        guard let url = Bundle.module.url(
            forResource: name,
            withExtension: ext,
            subdirectory: "Fixtures"
        ) else {
            throw FixtureError.missing("\(name).\(ext)")
        }
        return url
    }

    static func data(_ name: String, extension ext: String) throws -> Data {
        try Data(contentsOf: url(name, extension: ext))
    }

    static func text(_ name: String, extension ext: String) throws -> String {
        guard let string = String(data: try data(name, extension: ext), encoding: .utf8) else {
            throw FixtureError.notUTF8("\(name).\(ext)")
        }
        return string
    }

    static func json(_ name: String, extension ext: String) throws -> Any {
        try JSONSerialization.jsonObject(with: try data(name, extension: ext))
    }

    enum FixtureError: Error, CustomStringConvertible {
        case missing(String)
        case notUTF8(String)

        var description: String {
            switch self {
            case .missing(let name): return "Missing fixture: \(name)"
            case .notUTF8(let name): return "Fixture is not UTF-8: \(name)"
            }
        }
    }
}
